ALL_MODULES = MODULES + MODULES_2 + MODULES_3

GLOSSARY = [{'term': 'AET', 'def': 'Automation Engineering Technology — the applied industrial discipline covering PLCs, HMI/SCADA, VFDs, robotics, industrial networks, instrumentation, fluid power, and machine safety. AET graduates design, install, program, troubleshoot, and maintain automated systems in manufacturing, logistics, utilities, and process industries. The discipline bridges electrical theory, controls, and mechanical systems. Common credentials include ISA CCST, SACA certifications, and manufacturer programs from Rockwell, Siemens, FANUC, and Beckhoff.'}, {'term': 'PLC', 'def': 'Programmable Logic Controller — a ruggedized industrial computer designed for real-time discrete and analog control. Executes a scan cycle: read all inputs, solve ladder/function-block logic, write outputs, then housekeeping tasks. Built to withstand vibration, temperature extremes, and electrical noise on the factory floor. Supports IEC 61131-3 languages (Ladder, ST, FBD, SFC), tag-based addressing, motion control, and high-speed counters. Common families: Allen-Bradley ControlLogix/CompactLogix, Siemens S7, Mitsubishi, Omron. Typical scan time 1-20 ms.'}, {'term': 'HMI', 'def': 'Human-Machine Interface — the operator panel or touchscreen that bridges humans and automated systems. Displays real-time process data (PV values, alarms, trends) and allows setpoint entry and mode selection. Communicates with PLCs via OPC-UA, Ethernet/IP, Modbus, or PROFINET. Built with tag databases that mirror PLC data. Alarm management following ISA-18.2 is a critical HMI discipline. Modern HMIs support responsive HTML5 web clients, multi-touch, and cloud historian connectivity. HMI is machine-level; SCADA is plant-level.'}, {'term': 'SCADA', 'def': 'Supervisory Control And Data Acquisition — a distributed control architecture for monitoring and managing geographically spread assets (pipelines, power grids, water treatment, large factories). Aggregates data from multiple PLCs, RTUs, and field instruments via OPC-UA or Modbus. SCADA software (Ignition, Wonderware, iFIX, WinCC) provides trending, alarming, historian databases, and reporting. Cybersecurity is critical: IEC 62443 defines defense-in-depth zones for SCADA. Air-gapping vs. cloud historian is an active trade-off in modern deployments.'}, {'term': 'VFD', 'def': 'Variable Frequency Drive — an electronic power converter that controls AC induction motor speed by adjusting output frequency and voltage. Core sections: rectifier (AC to DC), DC bus (capacitor bank, approx. 650 V DC for 480 V input), and inverter (DC to AC via PWM IGBTs). Maintaining constant V/Hz ratio preserves rotor flux. Benefits: soft-start reduces inrush (up to 600% FLA), energy savings on centrifugal loads (cube law), process speed control. Common faults: overcurrent (OC), overvoltage (OV), ground fault, overtemperature.'}, {'term': 'OPC-UA', 'def': 'Open Platform Communications Unified Architecture — a vendor-neutral, platform-independent industrial data exchange standard (IEC 62541). Provides a unified information model where data, methods, and events are exposed as addressable nodes in a tree. Supports client-server and pub/sub (OPC-UA PubSub over MQTT/UDP). Built-in security: certificate-based authentication, message signing, and encryption. Supersedes legacy OPC-DA/HDA (COM/DCOM). Used as the integration layer between PLCs, SCADA, MES, and cloud analytics. Data semantics travel with the data, eliminating mapping spreadsheets.'}, {'term': 'IIoT', 'def': 'Industrial Internet of Things — connecting factory equipment, sensors, and controllers to networks for data collection, remote monitoring, and analytics. IIoT architectures layer edge devices (smart sensors, gateways) to fog/edge computing (local processing) to cloud platforms (Azure IoT, AWS IoT, PTC ThingWorx). Common protocols: MQTT, OPC-UA PubSub, AMQP, HTTP REST. Enables predictive maintenance (vibration trending, thermal imaging), OEE tracking, and digital twin models. Security and determinism requirements separate IIoT from consumer IoT.'}, {'term': 'MQTT', 'def': 'Message Queuing Telemetry Transport — a lightweight pub/sub messaging protocol (ISO/IEC 20922) for constrained devices and unreliable networks. Devices publish to topics (e.g. factory/line1/conveyor/speed); subscribers receive matching topics via a central broker (Mosquitto, EMQX, AWS IoT Core). QoS levels: 0 (fire-and-forget), 1 (at-least-once), 2 (exactly-once). Last Will and Testament enables disconnection detection. Sparkplug B adds structured payloads and birth/death certificates for industrial SCADA-grade MQTT. Default port 1883 (unencrypted), 8883 (TLS).'}, {'term': 'Ladder Logic', 'def': 'Graphical PLC programming language that represents relay-based control circuits as horizontal rungs between two vertical power rails. Left side is the logic (contacts XIC/XIO, function blocks); right side is the output (coil OTE, set/reset, function blocks). Reads left-to-right, top-to-bottom. Execution is deterministic within one scan cycle. Strengths: intuitive for electricians familiar with relay schematics, easy to trace live current flow during diagnostics. Weaknesses: complex math and string operations are cumbersome. Standardized in IEC 61131-3; dominant language for discrete manufacturing.'}, {'term': 'Structured Text', 'def': 'Text-based IEC 61131-3 PLC programming language with Pascal-like syntax. Supports IF/THEN/ELSIF/ELSE, CASE, FOR, WHILE, REPEAT loops, and full arithmetic expressions. Excellent for complex calculations, string handling, recipe management, and algorithm implementation. More compact than ladder for math-heavy logic. Variables are strongly typed (BOOL, INT, DINT, REAL, STRING). Function blocks and methods promote reuse. Increasingly popular in motion control, robotics, and data processing. Can be combined with Ladder, FBD, and SFC in the same project.'}, {'term': 'AOI', 'def': 'Add-On Instruction — a reusable custom PLC logic block in Rockwell Automation Studio 5000 / Logix environment. Encapsulates a complete routine (Ladder, ST, or FBD) with defined input, output, and inout parameters plus local tags. Once created, an AOI behaves like a native instruction and can be dropped on any rung. Changes to the definition propagate to all instances with revision control. AOIs promote modular programming, reduce duplication, and enable tested, documented logic libraries. Analogous to Function Blocks in IEC 61131-3. Critical for large-scale machine programming.'}, {'term': 'UDT', 'def': 'User-Defined Type — a custom data structure in Allen-Bradley Logix that groups related tags into a single named compound type. Example: a Motor_Type UDT might contain Running (BOOL), Fault (BOOL), Speed (REAL), and Setpoint (REAL). UDTs enforce consistency across all motor instances in a program. Nested UDTs and arrays are supported. Used to build tag templates for equipment faceplates in FactoryTalk View. Analogous to STRUCT in IEC 61131-3. Changing the UDT definition updates all tags of that type. Essential for scalable, maintainable PLC programs.'}, {'term': 'FBD', 'def': 'Function Block Diagram — an IEC 61131-3 graphical PLC programming language where logic is expressed as interconnected function blocks with signal lines. Inputs feed into blocks (AND, OR, TON, PID, ADD, etc.) and outputs wire to subsequent blocks or output variables. Data flows left to right. Excellent for analog control loops, mathematical processing, and signal conditioning. Widely used in process industries (DCS systems). Less intuitive for discrete on/off logic compared to Ladder. Supported in all major PLC/DCS platforms including Siemens, Rockwell, Beckhoff, and ABB.'}, {'term': 'SFC', 'def': 'Sequential Function Chart — an IEC 61131-3 graphical PLC programming language based on Petri-net / Grafcet notation. Represents sequential machine behavior as Steps (actions) connected by Transitions (conditions). Only active steps execute at a time; a transition fires when its Boolean condition is met. Supports divergence (parallel branches) and convergence. Each step can contain sub-routines in any other IEC language. Ideal for batch processes, pick-and-place robots, and complex multi-step machine sequences. Supported in Siemens GRAPH, Rockwell Phase Manager, and Beckhoff TwinCAT.'}, {'term': 'XIC', 'def': 'Examine If Closed — a normally-open contact instruction in Allen-Bradley Ladder Logic. The rung segment passes power continuity (evaluates TRUE) when the referenced bit tag equals 1 (ON). Maps to a physical input (switch closed means input module bit = 1) or an internal control bit. XIC is the most common contact instruction: motor run permissives, start pushbutton logic, and status conditions all use XIC. In IEC 61131-3 / non-AB PLCs, this is the standard normally-open (NO) contact. During live diagnostics, a highlighted XIC shows the bit is energized; dim means the bit is 0.'}, {'term': 'XIO', 'def': 'Examine If Open — a normally-closed contact instruction in Allen-Bradley Ladder Logic. The rung segment passes power continuity (evaluates TRUE) when the referenced bit tag equals 0 (OFF). Used for normally-closed inputs (E-stop, overload relay), fault interlock conditions, and stop pushbutton logic. XIO is the logical complement of XIC. Important distinction: a physical NC switch open means input bit = 0 means XIO is TRUE (passes power). Confusing wiring failures often arise from misunderstanding XIO behavior. In IEC 61131-3 / non-AB PLCs, this is the normally-closed (NC) contact.'}, {'term': 'OTE', 'def': 'Output Energize — the standard output coil instruction in Allen-Bradley Ladder Logic. When the preceding rung logic evaluates TRUE (power flows), the OTE sets the referenced bit tag to 1 (ON). When the rung evaluates FALSE, the OTE resets the bit to 0 (OFF) — it is not retentive. This non-retentive behavior distinguishes OTE from OTL (latch) and OTU (unlatch). Only one OTE per tag is best practice; duplicate OTEs on different rungs cause last-rung-wins behavior that produces intermittent faults. In IEC 61131-3 notation, this is the standard coil output.'}, {'term': 'TON', 'def': 'Timer On-Delay — accumulates elapsed time while the input rung is continuously TRUE; the Done (DN) bit sets when accumulated value equals the preset. If the input goes FALSE before preset, the accumulated value resets to zero. Parameters: Preset (PT), Accumulated (AC), Enable (EN) bit, Done (DN) bit. Used for: conveyor jam timers, motor run-up confirmation delays, alarm confirmation delays, and sequence timing. Distinguish from TOF (timer off-delay, DN bit resets after input drops) and RTO (retentive timer, accumulator holds value when input drops). Time base: 1 ms in modern PLCs.'}, {'term': 'CTU', 'def': 'Count Up — accumulates a count value by incrementing once on each FALSE-to-TRUE transition of the input rung (rising edge). The Count Up Done (CU DN) bit sets when the accumulated count reaches the preset value. The accumulated value holds until a reset (RES) instruction or CTD (Count Down) instruction is applied. Used for: parts counting, cycle counting, fault occurrence tracking, and batch counting. Works as a pair with CTD (Count Down) for bidirectional counting. The Overflow (OV) bit sets if the count exceeds the maximum DINT value.'}, {'term': 'NPN', 'def': 'Sinking sensor or output — the signal transistor connects the load to 0 V (ground/negative rail) when active. Common in 3-wire DC proximity sensors and output cards with sink wiring. In a sinking sensor circuit, the load (PLC input card) connects between the positive supply (+24 V) and the sensor output pin; the sensor pulls the output to 0 V when triggered. NPN sensors are standard in Asian and many European designs. Color code: brown = +24 V, blue = 0 V/common, black = signal output. Do not confuse with PNP (sourcing); the two types require opposite input card configurations.'}, {'term': 'PNP', 'def': 'Sourcing sensor or output — the signal transistor connects the load to the positive supply (+24 V) when active. Common in 3-wire DC proximity sensors and output cards with source wiring. In a sourcing sensor circuit, the load (PLC input card) connects between the sensor output pin and the negative rail (0 V); the sensor drives the output to +24 V when triggered. PNP sensors are standard in North American industrial designs. Color code: brown = +24 V, blue = 0 V/common, black = signal output. Cannot wire PNP sensor to NPN input card without an external pull-down resistor or signal converter.'}, {'term': '4-20 mA', 'def': 'The dominant analog process signal standard: 4 mA represents the zero/minimum value (live zero) and 20 mA represents the full-scale/maximum value. The live zero at 4 mA allows the system to distinguish a valid zero reading from a broken wire or failed transmitter (which would read 0 mA). Scales linearly: 12 mA = 50% of range. Two-wire (loop-powered) transmitters draw operating power from the loop itself. Three-wire and four-wire transmitters have separate power supply connections. Transmission range up to 300 m; not susceptible to voltage drop errors unlike 0-10 V signals.'}, {'term': 'RTD', 'def': 'Resistance Temperature Detector — a precision temperature sensor whose electrical resistance increases predictably with temperature. Most common types: PT100 (100 Ohm at 0 C, DIN 43760 curve) and PT1000 (1000 Ohm at 0 C). High accuracy, excellent long-term stability, and wide range (-200 C to +850 C). Requires 2-, 3-, or 4-wire connection; 3-wire and 4-wire compensate for lead resistance error. Used where high precision is required: pharmaceutical, food processing, and heat treating. Distinguished from thermocouples by higher accuracy and cost, and absence of the Seebeck effect reference junction requirement.'}, {'term': 'Thermocouple', 'def': 'Temperature sensor that generates a small millivolt EMF (Seebeck effect) from the junction of two dissimilar metals. Common types: J (iron/constantan, -40 to 750 C), K (chromel/alumel, -200 to 1260 C, most common), T (copper/constantan, cryogenic to 350 C), and E/R/S (high-temperature and precision). Requires reference junction compensation (cold junction compensation, CJC) at the measuring instrument. Robust, self-powered, and suitable for high temperatures where RTDs fail. Thermocouple extension wire must match thermocouple type to avoid measurement errors.'}, {'term': 'Encoder', 'def': 'Electromechanical position and speed feedback device attached to a rotating shaft or linear axis. Incremental encoders output quadrature A/B pulses per revolution (PPR); counting A/B edges gives direction and position. The Z (index) pulse marks one revolution. Absolute encoders output a unique binary code for each position — no counting needed, position known at power-up. Resolution in PPR (incremental) or bits (absolute). Outputs: HTL (high-voltage push-pull), TTL (5 V), or SinCos (analog). Used in servo drives, conveyors, robotics, and CNC machines. Verify supply voltage, signal voltage, and line termination.'}, {'term': 'PPR', 'def': 'Pulses Per Revolution — the resolution specification of an incremental rotary encoder, indicating how many electrical pulses are generated per full shaft revolution on a single output channel (A or B). Common values: 100, 256, 500, 1000, 2048, 2500, 5000 PPR. The PLC or drive counts these pulses to calculate position and speed. With quadrature decoding (4x multiplication of A and B edges), a 1000 PPR encoder yields 4000 counts/rev, improving position resolution without hardware changes. Higher PPR provides finer resolution but increases noise susceptibility and counter speed requirements.'}, {'term': 'V/Hz', 'def': 'Volts per Hertz — the voltage-to-frequency ratio maintained constant by a VFD in V/Hz (scalar) control mode to preserve motor magnetic flux across speed ranges. At 60 Hz/480 V, the ratio is 8 V/Hz. If frequency drops to 30 Hz, voltage drops to 240 V — keeping flux constant, torque capacity is preserved. Boost voltage at low speed (V/Hz boost) compensates for stator resistance losses and improves low-speed torque. V/Hz is simpler than vector control but has poorer low-speed torque accuracy. Used for centrifugal pumps, fans, and conveyor loads where speed range is moderate.'}, {'term': 'IGBT', 'def': 'Insulated-Gate Bipolar Transistor — the power semiconductor switching device used in the inverter section of modern VFDs and servo drives. Combines MOSFET voltage-controlled gate (easy to drive) with BJT low on-state voltage drop (efficient at high currents). Switches at 2-20 kHz (carrier frequency), synthesizing an AC waveform from DC bus voltage via PWM. Higher carrier frequency reduces audible motor noise but increases switching losses and leakage current. IGBT gate drivers include desaturation protection and soft-turn-off to prevent latch-up. Common failure modes: overvoltage transient, overcurrent, and thermal degradation.'}, {'term': 'DC Bus', 'def': 'The internal DC voltage rail inside a VFD or servo drive, formed by rectifying the AC input through a diode bridge and filtering with a large capacitor bank. For a 480 V AC input, DC bus voltage is approximately 650-680 V DC. Capacitors store energy and filter rectifier ripple. Overvoltage fault (OV) occurs when regenerated energy from decelerating motors pushes bus voltage above threshold (approx. 800 V for 480 V drives). Dynamic braking resistors (DBR) dissipate this regenerated energy as heat. DC bus undervoltage (UV) trips on power loss or low input voltage.'}, {'term': 'FRL', 'def': 'Filter-Regulator-Lubricator — the three-stage pneumatic air preparation assembly installed at the entry of each machine compressed air supply. Filter stage: removes water, particulates, and oil aerosols using a centrifugal bowl and filter element (typically 5-40 micron). Regulator stage: sets and maintains downstream working pressure regardless of supply fluctuations; adjusted via a knurled knob with a pressure gauge. Lubricator stage: adds a fine oil mist for cylinders and air motors that require lubrication (omit for dry-running solenoid valves). Bowl drain can be manual or auto; inspect and drain weekly.'}, {'term': 'DCV', 'def': 'Directional Control Valve — a pneumatic or hydraulic valve that controls the path and direction of flow through a circuit. Described by ports x positions notation: a 5/2 valve has 5 ports (pressure, exhaust x2, cylinder extend, cylinder retract) and 2 positions (extend/retract). Common types: 3/2 (single-acting cylinder), 5/2 and 5/3 (double-acting cylinder). Actuated by solenoids (electrically), air pilot, manual, or spring return. Spool valves shift to route flow; poppet valves use a seated plug. Response time is 10-50 ms for solenoid DCVs. Coil voltage: 24 VDC or 120 VAC.'}, {'term': "Pascal's Law", 'def': 'Fundamental hydraulics principle: pressure applied to a confined, static fluid is transmitted undiminished and equally in all directions throughout the fluid and to the walls of the container. Expressed as F = P x A, where F is force (N or lbf), P is pressure (Pa or psi), and A is the cross-sectional area of the piston. This enables hydraulic force multiplication: a small input force on a small piston creates high pressure that produces large force on a larger piston. Foundation of all hydraulic jacks, cylinders, and presses. Combined with continuity of flow (Q = A x v), it governs hydraulic power.'}, {'term': 'PID', 'def': 'Proportional-Integral-Derivative — the most common closed-loop feedback control algorithm. Proportional term (P): output proportional to current error (SP minus PV); fast response but leaves steady-state offset. Integral term (I): output proportional to accumulated past error; eliminates steady-state offset but can cause wind-up. Derivative term (D): output proportional to rate of error change; reduces overshoot but amplifies noise. Tuning methods: Ziegler-Nichols (step response or sustained oscillation), IMC, or manual. Key parameters: Kp (gain), Ti (integral time), Td (derivative time). Implemented in PLC function blocks and DCS loops.'}, {'term': 'SP/PV/CV', 'def': 'Three fundamental variables in any closed-loop control system. Setpoint (SP): the desired target value set by the operator or recipe (e.g., 75 C, 500 RPM, 5 psi). Process Variable (PV): the actual measured value from the field sensor (thermocouple, encoder, pressure transmitter). Control Variable (CV, also called Manipulated Variable or Output): the signal the controller sends to the final control element (valve position, drive speed reference, heater duty cycle) to drive PV toward SP. Error = SP minus PV. Monitoring all three on an HMI trend is the first step in diagnosing loop performance issues.'}, {'term': 'ISA-5.1', 'def': 'ANSI/ISA-5.1 Instrumentation Symbols and Identification — the standard defining tag letters, symbols, and graphic conventions used on P&IDs. First letter identifies the measured variable (T=temperature, P=pressure, F=flow, L=level, A=analyzer). Subsequent letters identify the function (T=transmitter, C=controller, I=indicator, A=alarm, V=valve). Example: FIC-101 = Flow Indicating Controller, loop 101. Instrument lines: solid = process, dashed = pneumatic, dotted = electrical/digital. Essential for reading plant P&IDs, specifying instruments, and communicating with process engineers. Updated edition 2009.'}, {'term': 'P&ID', 'def': 'Piping and Instrumentation Diagram — the master engineering drawing for a process system, showing all process equipment, piping, instrumentation, control loops, and their interconnections. Uses ISA-5.1 symbols and tag conventions. Includes: vessels, heat exchangers, pumps, compressors, valves (control, block, check, relief), instruments (sensors, transmitters, controllers), and their signal connections (pneumatic, electrical, digital). The primary reference for commissioning, troubleshooting, and modification of process plants. Must be kept as-built — all plant changes must be reflected. Controlled document requiring engineering approval.'}, {'term': 'LOTO', 'def': 'Lockout/Tagout — the OSHA 29 CFR 1910.147 standard procedure for controlling hazardous energy (electrical, pneumatic, hydraulic, thermal, mechanical, chemical, gravitational) before maintenance or servicing. Steps: notify affected employees, identify all energy sources, shut down equipment, isolate all energy sources (open disconnects, close valves), apply personal lock(s) to each isolation point, release stored energy (bleed pneumatics, discharge capacitors, block gravity loads), verify zero energy state. Each authorized employee applies their own lock. Tagout is used when lockout is not feasible. LOTO violations are among OSHA most frequently cited.'}, {'term': 'NFPA 70E', 'def': 'Standard for Electrical Safety in the Workplace — published by the National Fire Protection Association. Defines requirements for safe work practices on or near energized electrical equipment to protect against arc flash and shock hazards. Key requirements: Energized Electrical Work Permit for justified live work, arc flash hazard analysis (incident energy calculation per IEEE 1584 or PPE category method), PPE selection by arc flash boundary and incident energy (cal/cm2), and approach boundaries (Limited, Restricted, Prohibited). Panel labels must display incident energy, working distance, PPE category, and boundary distances. Updated every 3 years.'}, {'term': 'NFPA 79', 'def': 'Electrical Standard for Industrial Machinery — NFPA 79 specifies requirements for the electrical/electronic equipment, apparatus, and systems on industrial machines to protect personnel and property. Covers: control panel construction (wiring methods, wire sizing, color coding: blue=24VDC, black=120VAC, green=ground), component marking, enclosure ratings (NEMA/IP), disconnecting means (main disconnect at panel door), conductor protection, and grounding. Wire color conventions differ from NEC: orange for ungrounded AC is common. Applies to machine tools, packaging machines, conveyors, and robots. Closely aligned with IEC 60204-1.'}, {'term': 'ISO 13849', 'def': 'Safety of Machinery standard that defines requirements for designing and validating safety functions in control systems. Assigns a Performance Level (PL a through PL e) based on Category (structural architecture B, 1, 2, 3, or 4 — redundancy and diagnostics), Mean Time to Dangerous Failure (MTTFd), and Diagnostic Coverage (DC). Higher PLs require redundant channels, cross-monitoring, and proof testing. The required PL is determined by risk assessment per ISO 12100. Software tool SISTEMA (from IFA) calculates achieved PL from component data. Commonly implemented with safety relays (PILZ PNOZ), safety PLCs, or safety I/O modules.'}, {'term': 'Performance Level', 'def': 'ISO 13849 metric for quantifying the safety integrity of a machine safety-related control system. Levels range from PL a (lowest, suitable for low-risk applications) to PL e (highest, required for high-probability severe injury/death scenarios). Each level is defined by a maximum allowable Probability of Dangerous Failure per Hour (PFHd): PL a = 10e-5 to 10e-4, PL e at most 10e-7. Achieving a PL requires selecting the appropriate Category (architecture), MTTFd-rated components, and diagnostic coverage (DC) level. Risk assessment per ISO 12100 determines the required PLr; designers must achieve PLr or higher.'}, {'term': 'E-Stop', 'def': 'Emergency Stop — a safety control function that provides immediate cessation of hazardous machine motion upon activation. Classified per IEC 60204-1: Category 0 (immediate power removal, uncontrolled stop), Category 1 (controlled stop, then power removal), or Category 2 (controlled stop, power remains available). E-Stop devices: red mushroom-head push buttons on yellow background, pull cords, kick plates, and foot pedals. Must be self-latching (requires deliberate manual reset), directly wired to the safety circuit (not through PLC program alone), and monitored by a safety relay or safety PLC. Standards: ISO 13850, IEC 60204-1 clause 9.2.5.'}, {'term': 'IEC 62443', 'def': 'Industrial Automation and Control System (IACS) Cybersecurity standard series published jointly by ISA and IEC. Organized into four series: General (concepts/terminology), Policies and Procedures (asset owner requirements), System (security management system, zones/conduits), and Component (product security requirements). Key concept: Security Level (SL 1-4) defines required countermeasures based on threat actor capability. Zone and conduit model segments the control system by security level — field devices in one zone, SCADA in another, with firewalls/DMZ at conduit boundaries. Defense-in-depth: network segmentation, patch management, authentication, and audit logging.'}, {'term': 'SCCR', 'def': 'Short-Circuit Current Rating — the maximum prospective fault current (in amperes RMS symmetrical) that a complete industrial control panel or individual component can safely interrupt or withstand without creating a hazard. Required by NEC 409.110 and UL 508A for industrial panels. Must meet or exceed the available fault current at the panel installation point. Achieved through: properly rated main disconnect/fuse or circuit breaker, or series-rated combinations. Insufficient SCCR results in arc blast and equipment destruction. Listed on the panel nameplate; verify when adding loads or changing feeders.'}, {'term': 'MTBF', 'def': 'Mean Time Between Failures — a reliability metric for repairable systems. MTBF = Total operating time divided by Number of failures, expressed in hours. Higher MTBF = more reliable. Used for maintenance planning, spare parts stocking levels, and reliability-centered maintenance (RCM) decisions. Note: MTBF is NOT the same as the time until the next failure; it is a statistical average. Weibull analysis separates failure modes: early-life (infant mortality), random (useful life, constant failure rate), and wear-out. Availability = MTBF divided by (MTBF + MTTR). Tracked in CMMS/EAM systems.'}, {'term': 'MTTR', 'def': 'Mean Time To Repair — a maintainability metric measuring the average time required to restore a failed system to operational status. MTTR = Total downtime divided by Number of repair events, expressed in hours or minutes. Includes: detection time, response time (travel + parts retrieval), diagnostic time, repair/replacement time, and verification time. Reducing MTTR involves: better diagnostic tools (fault codes, trend data), organized spare parts cribs, documented troubleshooting procedures, cross-trained technicians, and clear escalation paths. Availability = MTBF divided by (MTBF + MTTR). Tracked in CMMS/EAM systems.'}, {'term': 'OEE', 'def': 'Overall Equipment Effectiveness — the gold-standard metric for measuring manufacturing productivity. OEE = Availability x Performance x Quality. Availability = (Planned production time minus Downtime) divided by Planned production time; accounts for unplanned stops and changeovers. Performance = (Ideal cycle time x Total count) divided by Run time; accounts for reduced speed and micro-stops. Quality = Good units divided by Total units produced; accounts for defects and rework. World-class OEE is approximately 85%. Each component highlights different loss categories (six big losses in TPM). OEE data drives continuous improvement prioritization.'}, {'term': 'FFT', 'def': 'Fast Fourier Transform — a computational algorithm that converts a time-domain vibration waveform into a frequency-domain spectrum, revealing which frequencies are present and at what amplitude. In predictive maintenance (PdM), FFT analysis of bearing, gear, and imbalance vibration identifies specific fault frequencies: BPFI/BPFO (bearing inner/outer race), BSF (ball spin), FTF (fundamental train frequency), gear mesh frequency, and 1x (imbalance) / 2x (misalignment) harmonics. Collected with a data collector (CSI 2130, SKF Microlog) or online monitoring systems. Alarm levels based on ISO 10816 or baseline comparison.'}, {'term': 'ISA CCST', 'def': 'Certified Control Systems Technician — the premier industry credential for instrumentation, control, and automation technicians, administered by the International Society of Automation (ISA). Three levels: I (entry, 3 years experience), II (journey, 5 years), III (senior, 9 years + Level II). Exam domains: loop measurement and calibration, troubleshooting, commissioning and decommissioning, process control, safety systems, and maintenance. 170+ questions (Level I), computer-based at Pearson VUE testing centers. Renewal: 3-year cycle with 60 PDHs or re-examination. Recognized internationally; frequently required for senior instrumentation technician roles.'}, {'term': 'SACA', 'def': 'Smart Automation Certification Alliance — a North American industry alliance that offers stackable Industry 4.0 and automation certifications aligned to workforce demand. Certification levels: Smart Automation Level 1 (fundamentals), Level 2 (advanced automation), and specialized credentials. Exam topics: industrial networking (Ethernet/IP, PROFINET, OPC-UA), PLCs, robotics, IIoT, cybersecurity basics, data analytics, and digital twins. Designed for community college AET/mechatronics graduates and incumbent workers. Exams are proctored online; renewal every 3 years. Recognized by FANUC, Rockwell Automation, Siemens, and other industry partners.'}, {'term': 'Ethernet/IP', 'def': 'Ethernet Industrial Protocol — an industrial application-layer protocol (CIP, Common Industrial Protocol) running over standard IEEE 802.3 Ethernet (TCP/UDP/IP). Developed by Rockwell Automation; now managed by ODVA. Uses TCP port 44818 for explicit messaging (configuration, program upload/download) and UDP port 2222 for implicit I/O messaging (cyclic real-time data). EDS (Electronic Data Sheet) files describe device capabilities. Supports Device Level Ring (DLR) topology for fault tolerance. RPI (Requested Packet Interval) sets I/O exchange rate (1-3200 ms). Most common industrial Ethernet in North American discrete manufacturing.'}, {'term': 'PROFINET', 'def': 'Process Field Network — Siemens-originated industrial Ethernet protocol standardized as IEC 61158/61784. Uses standard IEEE 802.3 hardware but adds PROFINET-specific application layers. Three classes: RT (Real-Time, approx. 1 ms cycle, UDP-based), IRT (Isochronous Real-Time, less than 1 ms, hardware timestamping for motion control), and NRT (non-real-time, TCP/IP, for configuration). Device identification: GSDML files describe device profiles for import into TIA Portal or Step 7. Supports MRP (Media Redundancy Protocol) ring topology. Dominant in European manufacturing and globally in Siemens-centric plants.'}, {'term': 'Modbus', 'def': 'The oldest and most widely supported open industrial communication protocol, developed by Modicon (now Schneider Electric) in 1979. Two variants: Modbus RTU (serial, RS-485/RS-232, compact binary encoding, up to 247 nodes at 9600-115200 baud) and Modbus TCP (frames encapsulated in TCP/IP packets, port 502). Function codes define operations: FC01 (read coils), FC03 (read holding registers), FC06 (write single register), FC16 (write multiple registers). Register model: coils (1-bit RW), discrete inputs (1-bit RO), holding registers (16-bit RW), input registers (16-bit RO). Supported by virtually every PLC, VFD, meter, and sensor.'}, {'term': 'RPI', 'def': 'Requested Packet Interval — the cyclic I/O data exchange rate configured for an Ethernet/IP implicit messaging connection, specified in milliseconds. The scanner (PLC) sends an I/O packet to the adapter (device) at the RPI rate; the adapter responds with its current input data. Typical values: 2-20 ms for discrete I/O, 10-100 ms for analog I/O, 1-5 ms for servo drives. Setting RPI too low: excessive network bandwidth, processor load, and potential I/O module faults. Setting RPI too high: sluggish control response and missed events. Configured in the PLC I/O tree. Connection timeout is typically 4x RPI.'}, {'term': 'DLR', 'def': 'Device Level Ring — a network fault-tolerance topology for Ethernet/IP devices defined by ODVA. Devices are connected in a ring; a Ring Supervisor (typically the PLC) monitors ring health and manages a single open port. If the ring cable is cut or a device fails, the supervisor detects the break and reconfigures the ring in less than 3 ms, maintaining I/O communications with all surviving devices. Requires DLR-capable managed switches or DLR-enabled device ports (many Allen-Bradley I/O modules include DLR hardware). A non-DLR device in the ring breaks DLR capability. Supervisor reports ring status and break location.'}, {'term': 'TCP/IP', 'def': 'Transmission Control Protocol / Internet Protocol — the foundational protocol suite for all Ethernet communication. IP provides addressing and routing (Layer 3): every device has an IP address and subnet mask. TCP provides reliable, ordered, connection-oriented transport (Layer 4): three-way handshake, acknowledgments, retransmission. UDP provides fast, connectionless transport (no guarantee of delivery, used for time-sensitive I/O where a dropped packet is less harmful than a delayed one). In industrial networks: static IP addressing is standard practice; DHCP is avoided for deterministic device identification. VLANs and managed switches segment industrial from IT traffic.'}, {'term': 'Scan Cycle', 'def': 'The fundamental execution loop of a PLC, repeated continuously during Run mode. Four phases: (1) Input Scan — the PLC reads all physical inputs and copies them to the input image table (IIT). (2) Program Scan — the PLC solves all logic rungs/function blocks top-to-bottom, left-to-right, using IIT values (inputs do NOT update mid-scan). (3) Output Scan — the PLC copies the output image table (OIT) to physical output terminals. (4) Housekeeping — communications, diagnostics, and watchdog timer reset. Typical scan time: 1-20 ms. Excessive scan time triggers a major fault. Critical for troubleshooting race conditions.'}, {'term': 'Seal-in', 'def': 'An auxiliary contact wired in parallel with the Start pushbutton to maintain the motor contactor coil circuit after the momentary Start button is released. Circuit operation: pressing Start energizes contactor coil M through NC Stop button; M auxiliary contact (M-aux) closes creating a parallel path; Start button released, but M-aux holds the coil energized. Pressing Stop opens the circuit, de-energizing M and opening M-aux. This classic two-wire latching circuit is found on virtually every NEMA motor starter. PLC implementations replace the physical auxiliary contact with a bit seal-in rung (XIC Motor_Run in parallel with XIC Start_PB).'}, {'term': 'Megohmmeter', 'def': 'An instrument that applies a high DC test voltage (typically 500 V or 1000 V) to motor or cable insulation and measures the resulting leakage current, expressing the result as insulation resistance in megohms. Used to detect insulation breakdown from moisture, contamination, mechanical damage, or thermal aging. IEEE 43-2013 guidelines: minimum acceptable IR at one minute is at least 1 MOhm per kV of rated voltage + 1 MOhm (rule of thumb). Polarization Index (PI) = IR at 10 min divided by IR at 1 min; PI greater than 2.0 indicates good insulation. Always discharge the winding after testing — lethal charge can accumulate. Lock out before connecting.'}, {'term': 'True RMS', 'def': 'True Root Mean Square — a meter measurement method that accurately computes RMS voltage or current for any waveform shape, including non-sinusoidal waveforms. Standard average-responding meters calibrated for sine waves read approximately 2-3% high on distorted waveforms; on the PWM output of a VFD (which has a very high crest factor), the error can be 30-40%. VFD output voltage and current measurements require a True RMS meter to be meaningful. Also required for: switch-mode power supplies, UPS output, and any load with harmonic content. Identified on the meter face as True RMS or TRMS. Fluke 87V and above are True RMS instruments.'}, {'term': 'CAT III/IV', 'def': 'IEC 61010-1 measurement category ratings that define the maximum transient overvoltage a test instrument can safely withstand. CAT III (Distribution level): equipment in fixed installations — distribution boards, motor control centers, 3-phase motors, industrial equipment directly connected to the distribution system. CAT IV (Origin of installation): service entrance, utility meters, overhead lines. Higher category = higher transient immunity. Using a CAT II meter (household) at a CAT III location is dangerous because transient spikes can destroy the meter and cause arc blast. Always match meter CAT rating to the measurement location.'}, {'term': 'Sparkplug B', 'def': 'An industrial MQTT specification (Eclipse Sparkplug) that standardizes how SCADA-class devices use MQTT. Defines: topic namespace structure (spBv1.0/group/message-type/edge-node/device), payload encoding (Google Protobuf binary, not JSON), birth/death certificate mechanism (NBIRTH/NDEATH/DBIRTH/DDEATH) for device lifecycle management, and rebirth commands for data synchronization. The birth certificate reports all data values and metadata on connect/reconnect, preventing stale data. Used with IIoT brokers (Ignition MQTT, HiveMQ, EMQX) to replace legacy polling-based SCADA with event-driven architectures.'}]

HTML = r'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>AET Course - Automation Engineering Technology (19 Modules)</title>
<style>
:root{--bg:#1a1a2e;--card:#16213e;--accent:#0f3460;--hi:#e94560;--text:#eee;--text2:#aab;--ok:#27ae60;--warn:#f39c12;--fail:#e74c3c;--r:10px}
*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:var(--bg);color:var(--text);display:flex;height:100vh;overflow:hidden}
#sb{width:290px;min-width:290px;background:var(--card);border-right:1px solid #333;overflow-y:auto;padding:0}
#sb-head{padding:1rem;border-bottom:1px solid #333;position:sticky;top:0;background:var(--card);z-index:2}
#sb-head h1{font-size:1rem;color:var(--hi);margin-bottom:.5rem}
#search{width:100%;padding:.4rem .6rem;border-radius:5px;border:1px solid #444;background:#111;color:#eee;font-size:.82rem}
#nav{padding:.5rem 0}.ni{padding:.5rem 1rem;cursor:pointer;border-left:3px solid transparent;font-size:.82rem;transition:all .15s;display:flex;align-items:center;gap:.4rem}
.ni:hover{background:var(--accent);border-left-color:var(--hi)}.ni.active{background:var(--accent);border-left-color:var(--hi);font-weight:600}
.ni .mn{color:var(--hi);font-weight:700;min-width:1.4rem}.ni .badge{margin-left:auto;font-size:.7rem;padding:1px 5px;border-radius:8px;background:var(--ok);color:#fff}
#main{flex:1;overflow-y:auto;padding:2rem 3rem}
.mh{margin-bottom:1.5rem}.mh h2{font-size:1.7rem;color:var(--hi);margin-bottom:.2rem}.mh .sub{color:var(--text2);font-size:.85rem}
.obj{background:var(--accent);border-radius:var(--r);padding:1rem 1.3rem;margin-bottom:1.5rem}.obj h3{color:var(--warn);margin-bottom:.5rem;font-size:.95rem}.obj li{margin:.3rem 0 .3rem 1.2rem;font-size:.88rem;line-height:1.5}
.sec{margin-bottom:1.8rem}.sec h3{color:var(--hi);font-size:1.1rem;margin-bottom:.6rem;border-bottom:1px solid #333;padding-bottom:.2rem}
.sec .bd{font-size:.9rem;line-height:1.7}.sec .bd b{color:#fff}.sec .bd pre{background:#111;padding:.7rem;border-radius:6px;overflow-x:auto;font-size:.8rem;margin:.5rem 0}.sec .bd code{background:#222;padding:2px 4px;border-radius:3px;font-size:.83rem}
.lab{background:#0a2a1a;border:1px solid var(--ok);border-radius:var(--r);padding:1rem 1.3rem;margin-bottom:1.5rem}.lab h3{color:var(--ok);margin-bottom:.2rem}.lab .tool{font-size:.8rem;color:var(--text2);margin-bottom:.5rem}.lab ol{margin-left:1.2rem;font-size:.88rem;line-height:1.7}
.qz{background:#1a1020;border:1px solid #555;border-radius:var(--r);padding:1rem 1.3rem;margin-bottom:1.5rem}.qz h3{color:var(--warn);margin-bottom:.8rem}
.qb{margin-bottom:1rem;padding-bottom:.8rem;border-bottom:1px solid #333}.qb:last-child{border-bottom:none}
.qt{font-size:.9rem;font-weight:600;margin-bottom:.4rem}.qo label{display:block;padding:.25rem .5rem;margin:.15rem 0;border-radius:4px;cursor:pointer;font-size:.85rem;transition:background .15s}.qo label:hover{background:#333}.qo input{margin-right:.4rem}
.qf{margin-top:.3rem;padding:.4rem .6rem;border-radius:5px;font-size:.83rem;display:none}.qf.c{display:block;background:#1a3a1a;color:var(--ok)}.qf.w{display:block;background:#3a1a1a;color:var(--fail)}
.res{margin-bottom:1.5rem}.res h3{color:var(--text2);margin-bottom:.4rem;font-size:.95rem}.res a{display:block;color:#5dade2;font-size:.85rem;margin:.2rem 0;text-decoration:none}.res a:hover{text-decoration:underline}
.pbar{position:fixed;top:0;left:290px;right:0;height:4px;background:#111;z-index:99}.pfill{height:100%;background:var(--hi);transition:width .3s}
.next-btn{background:var(--hi);color:#fff;border:none;padding:.7rem 1.8rem;border-radius:6px;cursor:pointer;font-size:.95rem;margin:1.5rem 0}
.next-btn:hover{opacity:.85}
#glossary{display:none;padding:2rem 3rem;overflow-y:auto}
#glossary h2{color:var(--hi);margin-bottom:1rem}
#glossary .gi{padding:.4rem 0;border-bottom:1px solid #222;font-size:.88rem}
#glossary .gi b{color:var(--warn)}
.tab-bar{display:flex;gap:0;border-bottom:1px solid #444;margin-bottom:1rem;position:sticky;top:0;background:var(--bg);z-index:5;padding-top:.5rem}
.tab{padding:.5rem 1.2rem;cursor:pointer;color:var(--text2);font-size:.9rem;border-bottom:2px solid transparent}.tab.active{color:var(--hi);border-bottom-color:var(--hi)}
.score-bar{margin:1.5rem 0;padding:1rem;background:var(--accent);border-radius:var(--r);font-size:.9rem}
.score-bar b{color:var(--ok)}
@media(max-width:900px){#sb{width:240px;min-width:240px}#main,#glossary{padding:1.2rem}}
@media(max-width:600px){body{flex-direction:column}#sb{width:100%;min-width:unset;max-height:180px;border-right:none;border-bottom:1px solid #333}#main,#glossary{padding:1rem}.pbar{left:0}}
.qlink{flex:1;min-width:80px;background:var(--accent);color:var(--text);border:1px solid #345;padding:.35rem;border-radius:5px;cursor:pointer;font-size:.72rem}.qlink:hover{background:var(--hi);color:#fff}
.sim{background:#0a1a2a;border:1px solid #5dade2;border-radius:var(--r);padding:1rem 1.3rem;margin-bottom:1.5rem}
.sim h3{color:#5dade2;margin-bottom:.3rem}.sim .desc{font-size:.83rem;color:var(--text2);margin-bottom:.7rem;line-height:1.5}
.sim label{display:block;font-size:.83rem;margin:.4rem 0 .15rem;color:var(--text2)}
.sim input,.sim select{width:100%;max-width:220px;padding:.35rem .5rem;border-radius:5px;border:1px solid #444;background:#111;color:#eee;font-size:.85rem}
.sim .row{display:flex;gap:1.2rem;flex-wrap:wrap;margin-bottom:.5rem}.sim .row>div{flex:1;min-width:150px}
.sim .out{margin-top:.8rem;padding:.7rem 1rem;background:#111;border-radius:6px;font-size:.9rem;line-height:1.6;border-left:3px solid #5dade2}
.sim .out b{color:#5dade2}.sim .big{font-size:1.3rem;color:var(--ok);font-weight:700}
.sim .btn{background:#5dade2;color:#03263d;border:none;padding:.4rem 1rem;border-radius:5px;cursor:pointer;font-weight:600;font-size:.85rem;margin-top:.4rem}
.sim .lamp{display:inline-block;width:14px;height:14px;border-radius:50%;background:#333;border:1px solid #666;vertical-align:middle}.sim .lamp.on{background:var(--ok);box-shadow:0 0 6px var(--ok)}
.exam-hd{background:var(--accent);border-radius:var(--r);padding:1.2rem 1.5rem;margin-bottom:1.5rem}.exam-hd h2{color:var(--hi)}.exam-hd p{font-size:.85rem;color:var(--text2);margin-top:.4rem;line-height:1.5}
.exresult{padding:1.2rem 1.5rem;border-radius:var(--r);margin-bottom:1.5rem;font-size:1rem}.exresult.pass{background:#0a2a1a;border:1px solid var(--ok)}.exresult.failg{background:#2a0a0a;border:1px solid var(--fail)}
@media print{
  #sb,.pbar,.tab-bar,.next-btn,.qz,.qo,.sim .btn,#printbtn,.res a{display:none!important}
  body{display:block;height:auto;overflow:visible;background:#fff;color:#000}
  #main,#glossary{display:block!important;padding:0;overflow:visible}
  .obj,.sec,.lab,.sim{background:#fff!important;border:1px solid #ccc!important;color:#000;page-break-inside:avoid}
  .mh h2,.sec h3,.obj h3,.lab h3,.sim h3{color:#000!important}
  .sec .bd b,.sec .bd pre,.sec .bd code{color:#000;background:#f0f0f0}
  a{color:#000;text-decoration:none}
  .printall .mh{page-break-before:always}
}
</style>
</head>
<body>
<div id="sb">
<div id="sb-head"><h1>&#9889; AET Course <span style="font-size:.7rem;color:var(--text2)">v3 &bull; 19 modules</span></h1><input id="search" placeholder="Search modules..." oninput="filterNav(this.value)"><div style="display:flex;gap:.3rem;margin-top:.5rem;flex-wrap:wrap"><button class="qlink" onclick="showExam()">&#127891; Final Exam</button><button class="qlink" onclick="showSims()">&#128300; Simulators</button><button class="qlink" onclick="printAll()">&#128424; Print All</button></div></div>
<div id="nav"></div>
</div>
<div class="pbar"><div class="pfill" id="progress"></div></div>
<div id="main"></div>
<div id="glossary"></div>
<script>
const M=__MODULES__;
const G=__GLOSSARY__;
let cur=0,scores=JSON.parse(localStorage.getItem('aet_scores')||'{}'),completed=JSON.parse(localStorage.getItem('aet_done')||'[]');
const nav=document.getElementById('nav'),main=document.getElementById('main'),gloss=document.getElementById('glossary'),prog=document.getElementById('progress');

function save(){localStorage.setItem('aet_scores',JSON.stringify(scores));localStorage.setItem('aet_done',JSON.stringify(completed));}
function buildNav(filter){
  const f=filter?filter.toLowerCase():'';
  nav.innerHTML=M.filter(m=>!f||m.title.toLowerCase().includes(f)).map(m=>{
    const done=completed.includes(m.id);
    return `<div class="ni${m.id===cur?' active':''}" onclick="showMod(${m.id})"><span class="mn">${m.id}</span>${m.title}${done?'<span class="badge">&#10003;</span>':''}</div>`;
  }).join('');
}
function filterNav(v){buildNav(v);}
function showMod(id){
  cur=id;gloss.style.display='none';main.style.display='block';buildNav();
  const m=M.find(x=>x.id===id);if(!m)return;
  let h=`<div class="tab-bar"><div class="tab active" onclick="showMod(${id})">Lesson</div><div class="tab" onclick="showGlossary()">Glossary (${G.length})</div></div>`;
  h+=`<div class="mh"><h2>Module ${m.id}: ${m.title}</h2><div class="sub">AET Course &mdash; Automation Engineering Technology</div></div>`;
  h+=`<div class="obj"><h3>&#127919; Learning Objectives</h3><ol>${m.objectives.map(o=>`<li>${o}</li>`).join('')}</ol></div>`;
  m.sections.forEach(s=>{h+=`<div class="sec"><h3>${s.h}</h3><div class="bd">${s.body}</div></div>`;});
  h+=`<div class="lab"><h3>&#128295; Hands-On Lab: ${m.lab.title}</h3><div class="tool">Tool: ${m.lab.tool}</div><ol>${m.lab.steps.map(s=>`<li>${s}</li>`).join('')}</ol></div>`;
  h+=`<div class="qz"><h3>&#128221; Check Your Understanding</h3>`;
  m.quiz.forEach((q,qi)=>{const qid=`q${id}_${qi}`;h+=`<div class="qb"><div class="qt">${qi+1}. ${q.q}</div><div class="qo" id="${qid}">${q.options.map((o,oi)=>`<label><input type="radio" name="${qid}" value="${oi}" onchange="chk(${id},${qi},${oi})">${o}</label>`).join('')}</div><div class="qf" id="${qid}_f"></div></div>`;});
  h+=`</div>`;
  const sc=scores[id];if(sc!==undefined)h+=`<div class="score-bar">Module score: <b>${sc}/${m.quiz.length}</b> correct${sc===m.quiz.length?' &#127942; Perfect!':''}</div>`;
  h+=`<div class="res"><h3>&#128218; Free Resources</h3>${m.resources.map(r=>`<a href="${r.url}" target="_blank">${r.name}</a>`).join('')}</div>`;
  if(id<M.length-1)h+=`<button class="next-btn" onclick="showMod(${id+1})">Next Module &rarr;</button>`;
  h+=`<button class="next-btn" style="background:#333;margin-left:.5rem" onclick="markDone(${id})">&#10003; Mark Complete</button>`;
  h+=`<button class="next-btn" id="printbtn" style="background:#5dade2;color:#03263d;margin-left:.5rem" onclick="printModule()">&#128424; Print Study Guide</button>`;
  main.innerHTML=h;main.scrollTop=0;
  prog.style.width=((completed.length)/M.length*100)+'%';
}
function chk(mid,qi,sel){
  const m=M.find(x=>x.id===mid),q=m.quiz[qi],fb=document.getElementById(`q${mid}_${qi}_f`);
  if(sel===q.answer){fb.className='qf c';fb.textContent='\u2713 Correct! '+q.explain;}
  else{fb.className='qf w';fb.textContent='\u2717 Incorrect. '+q.explain;}
  // score tracking
  if(!scores[mid])scores[mid]=0;
  const allQ=document.querySelectorAll(`[id^="q${mid}_"][id$="_f"]`);
  let correct=0;allQ.forEach(f=>{if(f.classList.contains('c'))correct++;});
  scores[mid]=correct;save();
}
function markDone(id){if(!completed.includes(id)){completed.push(id);save();showMod(id);}}
function showGlossary(){
  main.style.display='none';gloss.style.display='block';
  let h=`<div class="tab-bar"><div class="tab" onclick="showMod(cur)">Lesson</div><div class="tab active">Glossary (${G.length})</div></div>`;
  h+=`<h2>&#128214; AET Glossary (${G.length} terms)</h2>`;
  h+=`<input id="gsearch" placeholder="Filter terms..." oninput="filterGloss(this.value)" style="width:100%;padding:.4rem;margin-bottom:1rem;border-radius:5px;border:1px solid #444;background:#111;color:#eee">`;
  h+=`<div id="glist">${G.map(g=>`<div class="gi"><b>${g.term}</b> &mdash; ${g.def}</div>`).join('')}</div>`;
  gloss.innerHTML=h;
}
function filterGloss(v){
  const f=v.toLowerCase();
  document.getElementById('glist').innerHTML=G.filter(g=>g.term.toLowerCase().includes(f)||g.def.toLowerCase().includes(f)).map(g=>`<div class="gi"><b>${g.term}</b> &mdash; ${g.def}</div>`).join('');
}

function v(id){const e=document.getElementById(id);return e?e.value:0;}
// ---- Print ----
function printModule(){window.print();}
function printAll(){
  document.body.classList.add('printall');
  let h='';
  M.forEach(m=>{
    h+=`<div class="mh"><h2>Module ${m.id}: ${m.title}</h2></div>`;
    h+=`<div class="obj"><h3>Learning Objectives</h3><ol>${m.objectives.map(o=>`<li>${o}</li>`).join('')}</ol></div>`;
    m.sections.forEach(sc=>{h+=`<div class="sec"><h3>${sc.h}</h3><div class="bd">${sc.body}</div></div>`;});
    h+=`<div class="lab"><h3>Lab: ${m.lab.title}</h3><div class="tool">Tool: ${m.lab.tool}</div><ol>${m.lab.steps.map(x=>`<li>${x}</li>`).join('')}</ol></div>`;
  });
  h+=`<div class="mh"><h2>Glossary (${G.length} terms)</h2></div>`+G.map(g=>`<div class="gi"><b>${g.term}</b> &mdash; ${g.def}</div>`).join('');
  gloss.style.display='none';main.style.display='block';main.innerHTML=h;main.scrollTop=0;
  setTimeout(()=>{window.print();},350);
}
// ---- Lab Simulators ----
const SIM_SCALE=`<div class="sim"><h3>&#128225; 4-20 mA / Analog Scaling Calculator</h3>
<div class="desc">Convert a raw analog signal into engineering units. Live-zero: 4 mA = 0%, 20 mA = 100%. Below 4 mA usually means a broken wire.</div>
<div class="row"><div><label>Signal type</label><select id="sc_type" onchange="scale420()"><option value="ma">4-20 mA</option><option value="cnt">Raw counts (0-32767)</option></select></div>
<div><label>Input value</label><input id="sc_in" type="number" value="12" oninput="scale420()"></div></div>
<div class="row"><div><label>EU at min (0% / 4 mA)</label><input id="sc_lo" type="number" value="0" oninput="scale420()"></div>
<div><label>EU at max (100% / 20 mA)</label><input id="sc_hi" type="number" value="150" oninput="scale420()"></div></div>
<div class="out" id="sc_out"></div></div>`;
const SIM_REL=`<div class="sim"><h3>&#128202; Reliability &amp; OEE Calculator</h3>
<div class="desc">MTBF = uptime / failures. MTTR = downtime / repairs. Availability = MTBF / (MTBF + MTTR). OEE = Availability x Performance x Quality.</div>
<div class="row"><div><label>Operating hours</label><input id="r_up" type="number" value="720" oninput="calcRel()"></div>
<div><label>Number of failures</label><input id="r_f" type="number" value="4" oninput="calcRel()"></div>
<div><label>Total downtime (hrs)</label><input id="r_dn" type="number" value="8" oninput="calcRel()"></div></div>
<div class="row"><div><label>Performance %</label><input id="r_perf" type="number" value="95" oninput="calcRel()"></div>
<div><label>Quality %</label><input id="r_q" type="number" value="99" oninput="calcRel()"></div></div>
<div class="out" id="r_out"></div></div>`;
const SIM_VHZ=`<div class="sim"><h3>&#9881; VFD Motor Speed / V-Hz Calculator</h3>
<div class="desc">Synchronous RPM = 120 x f / poles. Slip = (Ns - Nfl) / Ns. Constant V/Hz keeps motor flux steady below base speed.</div>
<div class="row"><div><label>Line frequency (Hz)</label><input id="m_f" type="number" value="60" oninput="calcVHz()"></div>
<div><label>Motor poles</label><select id="m_p" onchange="calcVHz()"><option>2</option><option selected>4</option><option>6</option><option>8</option></select></div></div>
<div class="row"><div><label>Nameplate voltage (V)</label><input id="m_v" type="number" value="460" oninput="calcVHz()"></div>
<div><label>Full-load RPM (nameplate)</label><input id="m_fl" type="number" value="1750" oninput="calcVHz()"></div></div>
<div class="out" id="m_out"></div></div>`;
const SIM_SEAL=`<div class="sim"><h3>&#128268; Start / Stop Seal-In Logic Simulator</h3>
<div class="desc">Classic 3-wire motor control. Start is momentary; the run relay's aux contact "seals in" around it. Stop (NC) or an overload trip drops the coil.</div>
<div class="row"><div><button class="btn" onmousedown="sealStart(1)" onmouseup="sealStart(0)" onmouseleave="sealStart(0)" ontouchstart="sealStart(1)" ontouchend="sealStart(0)">HOLD Start PB</button></div>
<div><button class="btn" style="background:var(--fail);color:#fff" onclick="sealStop()">Press Stop PB</button></div>
<div><button class="btn" style="background:var(--warn);color:#000" id="seal_ol" onclick="sealOL()">Trip Overload</button></div></div>
<div class="out" id="seal_out"></div></div>`;
function showSims(){
  cur=-1;gloss.style.display='none';main.style.display='block';buildNav();
  main.innerHTML=`<div class="tab-bar"><div class="tab" onclick="showMod(0)">Modules</div><div class="tab active">Lab Simulators</div></div>`+
    `<div class="mh"><h2>&#128300; Lab Simulators</h2><div class="sub">Interactive tools &mdash; change any value to see live results. Great for practice before the real floor.</div></div>`+
    SIM_SCALE+SIM_REL+SIM_VHZ+SIM_SEAL;
  main.scrollTop=0;scale420();calcRel();calcVHz();sealDraw();
}
function scale420(){
  const t=document.getElementById('sc_type').value;
  const val=parseFloat(v('sc_in'))||0,lo=parseFloat(v('sc_lo'))||0,hi=parseFloat(v('sc_hi'))||0;
  let pct=(t==='ma')?(val-4)/16*100:val/32767*100;
  const eu=lo+(pct/100)*(hi-lo);
  const mm=(t==='ma')?val:(4+val/32767*16);
  document.getElementById('sc_out').innerHTML=`Percent of span: <b>${pct.toFixed(1)}%</b><br>Engineering value: <span class="big">${eu.toFixed(2)}</span><br>Equivalent current: <b>${mm.toFixed(2)} mA</b>`+((pct<0||pct>100)?'<br><span style="color:var(--warn)">&#9888; Out of 4-20 mA range &mdash; possible sensor fault / broken wire</span>':'');
}
function calcRel(){
  const up=parseFloat(v('r_up'))||0,f=parseFloat(v('r_f'))||0,dn=parseFloat(v('r_dn'))||0,perf=(parseFloat(v('r_perf'))||0)/100,ql=(parseFloat(v('r_q'))||0)/100;
  const mtbf=f>0?up/f:up,mttr=f>0?dn/f:0,avail=(mtbf+mttr)>0?mtbf/(mtbf+mttr):1,oee=avail*perf*ql;
  document.getElementById('r_out').innerHTML=`MTBF: <b>${mtbf.toFixed(1)} h</b> &nbsp; MTTR: <b>${mttr.toFixed(2)} h</b><br>Availability: <b>${(avail*100).toFixed(2)}%</b><br>OEE: <span class="big">${(oee*100).toFixed(1)}%</span> <span style="font-size:.8rem;color:var(--text2)">(world-class &ge; 85%)</span>`;
}
function calcVHz(){
  const f=parseFloat(v('m_f'))||0,p=parseFloat(v('m_p'))||4,vt=parseFloat(v('m_v'))||0,fl=parseFloat(v('m_fl'))||0;
  const ns=p>0?120*f/p:0,slip=ns>0?(ns-fl)/ns*100:0,vhz=f>0?vt/f:0;
  document.getElementById('m_out').innerHTML=`Synchronous speed: <b>${ns.toFixed(0)} RPM</b><br>Slip: <b>${slip.toFixed(1)}%</b><br>V/Hz ratio: <span class="big">${vhz.toFixed(2)} V/Hz</span> <span style="font-size:.8rem;color:var(--text2)">(460V / 60Hz &approx; 7.67)</span>`;
}
let sealRun=false,sealOLok=true;
function sealStart(down){if(down&&sealOLok)sealRun=true;sealDraw();}
function sealStop(){sealRun=false;sealDraw();}
function sealOL(){sealOLok=!sealOLok;if(!sealOLok)sealRun=false;const b=document.getElementById('seal_ol');if(b)b.textContent=sealOLok?'Trip Overload':'Reset Overload';sealDraw();}
function sealDraw(){
  const el=document.getElementById('seal_out');if(!el)return;
  el.innerHTML=`Motor coil M: <span class="lamp ${sealRun?'on':''}"></span> <b>${sealRun?'RUNNING':'stopped'}</b><br>Seal-in aux contact: <b>${sealRun?'closed (holding)':'open'}</b> &nbsp; Overload: <b>${sealOLok?'OK':'TRIPPED'}</b><br><span style="font-size:.8rem;color:var(--text2)">Tip: hold Start to energize, then release &mdash; the seal-in keeps the motor running until Stop or an overload trip.</span>`;
}
// ---- Final Exam ----
let examQ=[],examAns={},examResult=null;
function buildExamPool(){let p=[];M.forEach(m=>{if(m.quiz)m.quiz.forEach(q=>p.push({q:q.q,options:q.options,answer:q.answer,explain:q.explain,mod:m.id}));});return p;}
function showExam(){
  cur=-2;gloss.style.display='none';main.style.display='block';buildNav();
  const last=JSON.parse(localStorage.getItem('aet_exam')||'null');
  let h=`<div class="tab-bar"><div class="tab" onclick="showMod(0)">Modules</div><div class="tab active">Final Exam</div></div>`;
  h+=`<div class="exam-hd"><h2>&#127891; Final Exam</h2><p>20 questions drawn at random from all ${M.length} modules. Passing score: <b>80% (16/20)</b>. Retake as many times as you like &mdash; you get a fresh random set each attempt.</p>`;
  if(last)h+=`<p>Last attempt: <b style="color:${last.pct>=80?'var(--ok)':'var(--fail)'}">${last.score}/${last.total} (${last.pct}%)</b> &mdash; ${last.pct>=80?'PASS':'not passed yet'}</p>`;
  h+=`<button class="next-btn" style="margin-top:.8rem" onclick="startExam()">Start / Retake Exam &rarr;</button></div>`;
  main.innerHTML=h;main.scrollTop=0;
}
function startExam(){
  const pool=buildExamPool();
  for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const t=pool[i];pool[i]=pool[j];pool[j]=t;}
  examQ=pool.slice(0,Math.min(20,pool.length));examAns={};examResult=null;renderExam(false);
}
function examPick(qi,oi){examAns[qi]=oi;}
function renderExam(graded){
  let h=`<div class="tab-bar"><div class="tab" onclick="showMod(0)">Modules</div><div class="tab active">Final Exam</div></div>`;
  if(graded&&examResult){const pass=examResult.pct>=80;h+=`<div class="exresult ${pass?'pass':'failg'}"><b style="font-size:1.3rem;color:${pass?'var(--ok)':'var(--fail)'}">${pass?'\u2705 PASS':'\u274c Keep studying'}</b> &mdash; you scored <b>${examResult.score}/${examResult.total} (${examResult.pct}%)</b>. ${pass?'Nice work &mdash; solid AET fundamentals!':'Passing is 80%. Review the questions marked incorrect below and retake.'}</div>`;}
  h+=`<div class="mh"><h2>&#127891; Final Exam &mdash; ${examQ.length} questions</h2></div>`;
  examQ.forEach((q,qi)=>{
    const qid='ex'+qi;
    h+=`<div class="qb"><div class="qt">${qi+1}. ${q.q} <span style="font-size:.72rem;color:var(--text2)">[M${q.mod}]</span></div><div class="qo">`;
    q.options.forEach((o,oi)=>{
      let extra='';
      if(graded){if(oi===q.answer)extra=' style="color:var(--ok);font-weight:600"';else if(examAns[qi]===oi)extra=' style="color:var(--fail)"';}
      h+=`<label${extra}><input type="radio" name="${qid}" value="${oi}" ${examAns[qi]===oi?'checked':''} ${graded?'disabled':''} onchange="examPick(${qi},${oi})">${o}</label>`;
    });
    h+=`</div>`;
    if(graded){const ok=examAns[qi]===q.answer;h+=`<div class="qf ${ok?'c':'w'}" style="display:block">${ok?'\u2713 Correct':(examAns[qi]===undefined?'\u2717 No answer':'\u2717 Incorrect')}. ${q.explain}</div>`;}
    h+=`</div>`;
  });
  if(!graded)h+=`<button class="next-btn" onclick="gradeExam()">Submit Exam</button>`;
  else h+=`<button class="next-btn" onclick="startExam()">Retake (new questions) &rarr;</button> <button class="next-btn" style="background:#333;margin-left:.5rem" onclick="showExam()">Exam Home</button>`;
  main.innerHTML=h;main.scrollTop=0;
}
function gradeExam(){
  let score=0;examQ.forEach((q,qi)=>{if(examAns[qi]===q.answer)score++;});
  const total=examQ.length,pct=Math.round(score/total*100);
  examResult={score,total,pct};
  localStorage.setItem('aet_exam',JSON.stringify({score,total,pct,ts:Date.now()}));
  renderExam(true);
}
buildNav();showMod(0);
</script>
</body>
</html>'''

def build():
    d = os.path.dirname(os.path.abspath(__file__))
    mj = json.dumps(ALL_MODULES, ensure_ascii=False)
    gj = json.dumps(GLOSSARY, ensure_ascii=False)
    html = HTML.replace('__MODULES__', mj).replace('__GLOSSARY__', gj)
    p = os.path.join(d, 'AET_Course.html')
    with open(p, 'w', encoding='utf-8') as f:
        f.write(html)
    print(f"Built: {p} ({os.path.getsize(p):,} bytes, {len(ALL_MODULES)} modules, {len(GLOSSARY)} glossary terms)")

    # Outline
    op = os.path.join(d, 'COURSE_OUTLINE.md')
    with open(op, 'w', encoding='utf-8') as f:
        f.write("# AET Course - Automation Engineering Technology\n\n")
        f.write(f"**{len(ALL_MODULES)} Modules | Self-paced | Interactive HTML | Free tools | Progress saved locally**\n\n")
        f.write("**Audience:** Industrial maintenance technicians, RME techs, aspiring automation engineers\n")
        f.write("**Prerequisites:** High-school algebra, basic tool familiarity\n\n")
        f.write("## Modules\n\n")
        for m in ALL_MODULES:
            f.write(f"### Module {m['id']}: {m['title']}\n")
            f.writelines(f"- {o}\n" for o in m['objectives'])
            f.write(f"- **Lab:** {m['lab']['title']} ({m['lab']['tool']})\n")
            f.write(f"- **Quiz:** {len(m['quiz'])} questions\n\n")
        f.write("---\n*Open AET_Course.html for the full interactive experience.*\n")
    print(f"Built: {op} ({os.path.getsize(op):,} bytes)")

if __name__ == '__main__':
    build()
